// reviewer-f144-fb3-exhaustive-v1.cpp  (reviewer-authored; f144 same-harness review)
//
// Reads the 159-element multiplication table written by reviewer-f144-exact-controls-v1.py (control C7).
// Everything below is verified FROM THE TABLE ALONE (no Green-Rees import is needed for these facts):
//   (1) idempotent, (2) associative, (3) generated by the three marked generators  => it is a finite band;
//   (4) regular identity xyxzx = xyzx                        (expected to FAIL: FB(3) is not regular);
//   (5) local-regular identity (exe)(eye)(exe)(eze)(exe) = (exe)(eye)(eze)(exe)  over all e,x,y,z;
//   (6) (SN) abcda = abcacda over all a,b,c,d;
//   (7) control identity abcda = abacda (an instance of regularity; equivalent to it: put d:=c) - intended-reason control.
// The theorem under review predicts (5) and (6) agree on every band.
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <string>
int main(int argc, char** argv) {
    if (argc < 2) { std::fprintf(stderr, "usage: %s table.txt\n", argv[0]); return 2; }
    FILE* f = std::fopen(argv[1], "r");
    if (!f) { std::fprintf(stderr, "cannot open\n"); return 2; }
    int n = 0;
    if (std::fscanf(f, "%d", &n) != 1 || n <= 0 || n > 4096) { std::fprintf(stderr, "bad n\n"); return 2; }
    std::vector<std::string> reps(n);
    char buf[512];
    for (int i = 0; i < n; i++) { if (std::fscanf(f, "%511s", buf) != 1) return 2; reps[i] = buf; }
    int g[3];
    for (int i = 0; i < 3; i++) if (std::fscanf(f, "%d", &g[i]) != 1) return 2;
    std::vector<int> T((size_t)n * n);
    for (size_t i = 0; i < (size_t)n * n; i++) if (std::fscanf(f, "%d", &T[i]) != 1) { std::fprintf(stderr, "short table\n"); return 2; }
    std::fclose(f);
    auto M = [&](int x, int y) { return T[(size_t)x * n + y]; };
    for (size_t i = 0; i < (size_t)n * n; i++) if (T[i] < 0 || T[i] >= n) { std::printf("FAIL range\n"); return 1; }
    int fails = 0;
    long bad = 0;
    for (int i = 0; i < n; i++) if (M(i, i) != i) bad++;
    std::printf("%s (1) idempotent: %ld violations over %d elements\n", bad ? "FAIL" : "PASS", bad, n); if (bad) fails++;
    bad = 0;
    for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) { int xy = M(x, y); for (int z = 0; z < n; z++) if (M(xy, z) != M(x, M(y, z))) bad++; }
    std::printf("%s (2) associative: %ld violations over %ld triples\n", bad ? "FAIL" : "PASS", bad, (long)n * n * n); if (bad) fails++;
    std::vector<char> in(n, 0); std::vector<int> fr;
    for (int i = 0; i < 3; i++) { if (!in[g[i]]) { in[g[i]] = 1; fr.push_back(g[i]); } }
    while (!fr.empty()) { std::vector<int> nx; for (int w : fr) for (int i = 0; i < 3; i++) { int u = M(w, g[i]); if (!in[u]) { in[u] = 1; nx.push_back(u); } int v = M(g[i], w); if (!in[v]) { in[v] = 1; nx.push_back(v); } } fr.swap(nx); }
    int cnt = 0; for (int i = 0; i < n; i++) cnt += in[i];
    std::printf("%s (3) generated by %s,%s,%s: closure %d of %d\n", cnt == n ? "PASS" : "FAIL", reps[g[0]].c_str(), reps[g[1]].c_str(), reps[g[2]].c_str(), cnt, n); if (cnt != n) fails++;
    long regbad = 0; int rw[3] = {0, 0, 0};
    for (int x = 0; x < n; x++) for (int y = 0; y < n; y++) { int xy = M(x, y), xyx = M(xy, x); for (int z = 0; z < n; z++) if (M(M(xyx, z), x) != M(M(xy, z), x)) { if (!regbad) { rw[0] = x; rw[1] = y; rw[2] = z; } regbad++; } }
    std::printf("INFO (4) regular identity xyxzx=xyzx: %ld violations over %ld triples", regbad, (long)n * n * n);
    if (regbad) std::printf("; first witness x=%s y=%s z=%s", reps[rw[0]].c_str(), reps[rw[1]].c_str(), reps[rw[2]].c_str());
    std::printf("\n");
    long locbad = 0; int lw[4] = {0, 0, 0, 0};
    std::vector<int> loc(n);
    for (int e = 0; e < n; e++) {
        for (int x = 0; x < n; x++) loc[x] = M(M(e, x), e);
        for (int x = 0; x < n; x++) { int X = loc[x]; for (int y = 0; y < n; y++) { int XY = M(X, loc[y]), XYX = M(XY, X); for (int z = 0; z < n; z++) { int Z = loc[z]; if (M(M(XYX, Z), X) != M(M(XY, Z), X)) { if (!locbad) { lw[0] = e; lw[1] = x; lw[2] = y; lw[3] = z; } locbad++; } } } }
    }
    std::printf("INFO (5) local-regular identity: %ld violations over %ld quadruples -> %s", locbad, (long)n * n * n * n, locbad ? "FAILS" : "HOLDS");
    if (locbad) std::printf("; first witness e=%s x=%s y=%s z=%s", reps[lw[0]].c_str(), reps[lw[1]].c_str(), reps[lw[2]].c_str(), reps[lw[3]].c_str());
    std::printf("\n");
    long snbad = 0; int sw[4] = {0, 0, 0, 0};
    for (int a = 0; a < n; a++) for (int b = 0; b < n; b++) { int ab = M(a, b); for (int c = 0; c < n; c++) { int abc = M(ab, c), abcac = M(M(abc, a), c); for (int d = 0; d < n; d++) if (M(M(abc, d), a) != M(M(abcac, d), a)) { if (!snbad) { sw[0] = a; sw[1] = b; sw[2] = c; sw[3] = d; } snbad++; } } }
    std::printf("INFO (6) (SN) abcda=abcacda: %ld violations over %ld quadruples -> %s", snbad, (long)n * n * n * n, snbad ? "FAILS" : "HOLDS");
    if (snbad) std::printf("; first witness a=%s b=%s c=%s d=%s", reps[sw[0]].c_str(), reps[sw[1]].c_str(), reps[sw[2]].c_str(), reps[sw[3]].c_str());
    std::printf("\n");
    long rbad = 0;
    for (int a = 0; a < n; a++) for (int b = 0; b < n; b++) { int ab = M(a, b), aba = M(ab, a); for (int c = 0; c < n; c++) { int abc = M(ab, c), abac = M(aba, c); for (int d = 0; d < n; d++) if (M(M(abc, d), a) != M(M(abac, d), a)) rbad++; } }
    std::printf("INFO (7) control identity abcda=abacda (regular-type): %ld violations -> %s (must agree with (4))\n", rbad, rbad ? "FAILS" : "HOLDS");
    bool consistent = ((locbad == 0) == (snbad == 0));
    bool ctrl = ((regbad == 0) == (rbad == 0));
    std::printf("%s theorem consistency on this band: locally-regular=%s  SN=%s\n", consistent ? "PASS" : "FAIL", locbad ? "false" : "true", snbad ? "false" : "true");
    std::printf("%s control consistency: regular=%s  [abcda=abacda]=%s\n", ctrl ? "PASS" : "FAIL", regbad ? "false" : "true", rbad ? "false" : "true");
    if (!consistent || !ctrl) fails++;
    std::printf("RESULT %s (%d failing checks)\n", fails ? "FAIL" : "PASS", fails);
    return fails ? 1 : 0;
}
